            vals=[c.get('value') for c in x['cases']]
            hits=[v for v in vals if v and any(term in v.lower() for term in ['parsimony','informative','variable','alignment'])]
            if hits:
                print('CASES', path, name, hits)
        for k,v in x.items(): walk(v, path+'/'+str(k))
    elif isinstance(x, list):
        for i,v in enumerate(x): walk(v, path+'/'+str(i))
walk(t)
